from decimal import Decimal
from typing import Any


def _amount(value: Any) -> Decimal:
    """Apply legacy numeric coercion for the approve guard."""
    if value is None:
        return Decimal(0)
    if isinstance(value, str) and value.strip() == "":
        return Decimal(0)
    return Decimal(str(value))


def _account_credit_hold(record: dict, tables: dict) -> Any:
    """Return CRED_HOLD from the first live matching ACCT_MASTER row."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    record_copy = dict(record)

    if state == "E" and event == "approve":
        if _amount(record.get("TOT_AMT", "")) > 0:
            return {
                "state": "A",
                "record": record_copy,
                "audits": ["ORD_APPR"],
                "notifies": [],
                "matched": True,
            }

    elif state == "A" and event == "ship":
        return {
            "state": "S",
            "record": record_copy,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    elif state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": record_copy,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    elif state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": record_copy,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    elif state == "A" and event == "cancel":
        if _account_credit_hold(record, tables) != "Y":
            return {
                "state": "X",
                "record": record_copy,
                "audits": ["ORD_CANC"],
                "notifies": [],
                "matched": True,
            }

    elif state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": record_copy,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": record_copy,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
